/**
 * SAMPLE lesson track — synthetic GPS generated by a simple kinematic sim
 * (rate-limited heading / speed / altitude), so every turn is smooth and
 * every timestamp is coherent at 1 Hz. Clearly labeled SAMPLE; not a real flight.
 *
 * Profile: 17L departure → climb to practice area SE → steep turns (360° L, 360° R at 45°)
 * → slow flight → 45° entry to left downwind → touch-and-go → closed pattern →
 * bounced landing → full stop.
 */
import { enrich } from './parse.mjs';
import { detectEvents } from './events.mjs';

const KAPA = { lat: 39.5701, lon: -104.849, elev: 5885 };
const RWY_HDG = 170; // 17L (approx true)
const DEG = Math.PI / 180;

export function dest(lat, lon, brgDeg, distNm) {
  const R = 3440.065;
  const δ = distNm / R;
  const θ = brgDeg * DEG;
  const φ1 = lat * DEG;
  const λ1 = lon * DEG;
  const φ2 = Math.asin(Math.sin(φ1) * Math.cos(δ) + Math.cos(φ1) * Math.sin(δ) * Math.cos(θ));
  const λ2 = λ1 + Math.atan2(Math.sin(θ) * Math.sin(δ) * Math.cos(φ1), Math.cos(δ) - Math.sin(φ1) * Math.sin(φ2));
  return { lat: φ2 / DEG, lon: ((λ2 / DEG + 540) % 360) - 180 };
}
function distNm(a, b) {
  const dLat = (b.lat - a.lat) * 60;
  const dLon = (b.lon - a.lon) * 60 * Math.cos(a.lat * DEG);
  return Math.hypot(dLat, dLon);
}
function brg(a, b) {
  const dLat = b.lat - a.lat;
  const dLon = (b.lon - a.lon) * Math.cos(a.lat * DEG);
  return (Math.atan2(dLon, dLat) / DEG + 360) % 360;
}
const wrap = (d) => ((d + 540) % 360) - 180;
const approach = (v, target, maxStep) => v + Math.max(-maxStep, Math.min(maxStep, target - v));

/** Build SAMPLE track starting at a fixed UTC for stable demos. */
export function buildSampleKapaTrack({ startIso = '2024-05-18T14:15:00Z', airport = KAPA } = {}) {
  const E = airport.elev;
  const thr = { lat: airport.lat + 0.008, lon: airport.lon + 0.001 }; // 17L threshold (north end)
  const at = (b, d, from = thr) => dest(from.lat, from.lon, b, d);
  const s = { ...thr, alt: E, gs: 0, hdg: RWY_HDG, t: Date.parse(startIso) };
  const pts = [];
  const rec = () => pts.push({ t: s.t, lat: s.lat, lon: s.lon, altFt: Math.round(s.alt), gsKt: Math.round(s.gs * 10) / 10, hdgDeg: Math.round(((s.hdg % 360) + 360) % 360) });
  // one 1-s step: turnRate °/s (signed), target gs / alt with rate limits
  const step = ({ turn = 0, gs, alt, accel = 2, vs = 700 }) => {
    s.hdg += turn;
    if (gs != null) s.gs = approach(s.gs, gs, accel);
    if (alt != null) s.alt = approach(s.alt, alt, vs / 60);
    const p = dest(s.lat, s.lon, s.hdg, s.gs / 3600);
    s.lat = p.lat; s.lon = p.lon; s.t += 1000;
    rec();
  };
  const steerTurn = (target, maxRate = 3) => Math.max(-maxRate, Math.min(maxRate, wrap(brg(s, target) - s.hdg) * 0.25));
  // fly to waypoint with standard-rate rounded turns
  const goTo = (wp, { gs, alt, vs, rate = 3, within = 0.25 } = {}) => {
    for (let i = 0; i < 1500 && distNm(s, wp) > within; i++) step({ turn: steerTurn(wp, rate), gs, alt, vs });
  };
  const fly = (sec, o) => { for (let i = 0; i < sec; i++) step(o); };
  // constant-bank turn through `deg` (signed) at rate °/s
  const turnBy = (deg, rate, o) => {
    const n = Math.round(Math.abs(deg) / rate);
    for (let i = 0; i < n; i++) step({ ...o, turn: Math.sign(deg) * rate });
  };
  // 3° glidepath to threshold then flare
  const finalApproach = (gs) => {
    for (let i = 0; i < 400; i++) {
      const d = distNm(s, thr);
      if (d < 0.05 || wrap(brg(s, thr) - RWY_HDG) > 90) break;
      // track the extended centerline: aim at a lead point 0.4 nm closer on the centerline
      const along = d * Math.cos(wrap(brg(thr, s) - (RWY_HDG + 180)) * DEG);
      const aim = along > 0.45 ? at(RWY_HDG + 180, along - 0.4) : thr;
      step({ turn: steerTurn(aim, 3), gs, alt: E + 30 + d * 318, vs: 900 });
    }
  };
  const roll = (sec, gs, accel) => { for (let i = 0; i < sec; i++) { s.alt = E; step({ turn: wrap(RWY_HDG - s.hdg) * 0.3, gs, accel }); } };
  const climbOut = () => { for (let i = 0; i < 6; i++) step({ turn: wrap(RWY_HDG - s.hdg) * 0.3, gs: 75, alt: E + 400, vs: 700 }); };

  // Pattern geometry (left traffic 17L, downwind east of field, 0.8 nm offset)
  const rwyEnd = at(RWY_HDG, 1.6);
  const upwind = at(RWY_HDG, 2.4);
  const xwind = at(80, 0.8, upwind);
  const dwMid = at(80, 0.8, at(RWY_HDG, 0.8));
  const dwEnd = at(350, 1.3, at(80, 0.8));
  const baseEnd = at(80, 0.25, at(350, 1.7));
  const PA = E + 1000;

  rec();
  fly(25, { gs: 0, accel: 0 }); // run-up hold short / lined up
  roll(26, 65, 2.6); // takeoff roll
  climbOut();
  goTo(upwind, { gs: 79, alt: E + 1500 });
  // Departure to practice area SE, cruise-climb
  const practice = at(120, 9);
  goTo(practice, { gs: 100, alt: E + 2500, vs: 600 });
  fly(40, { gs: 95, alt: E + 2500 }); // clearing / set up
  // Steep turns: 45° bank at 95 kt → ω = g·tan45/V ≈ 11.5°/s → ~31 s per 360°
  turnBy(-360, 11.5, { gs: 95, alt: E + 2500 });
  fly(20, { gs: 95, alt: E + 2500 });
  turnBy(360, 11.5, { gs: 95, alt: E + 2500 });
  fly(30, { gs: 95, alt: E + 2500 });
  // Slow flight: slow to 55 kt, straight, gentle 90° turns, recover
  fly(25, { gs: 55, accel: 1.8, alt: E + 2500 });
  fly(60, { gs: 55, alt: E + 2500 });
  turnBy(90, 3, { gs: 55, alt: E + 2500 });
  fly(45, { gs: 55, alt: E + 2500 });
  turnBy(-90, 3, { gs: 55, alt: E + 2500 });
  fly(30, { gs: 55, alt: E + 2500 });
  fly(25, { gs: 100, accel: 1.5, alt: E + 2500 });
  // Return: 45° entry to left downwind
  const entry = at(135, 1.6, dwMid);
  goTo(entry, { gs: 105, alt: PA + 200, vs: 500 });
  goTo(dwMid, { gs: 90, alt: PA, vs: 500 });

  const circuit = () => {
    goTo(dwEnd, { gs: 80, alt: PA - 300, vs: 500 });
    goTo(baseEnd, { gs: 72, alt: E + 500, vs: 600, within: 0.3 });
    finalApproach(66);
  };
  // Circuit 1 → touch-and-go
  circuit();
  for (let i = 0; i < 4; i++) step({ turn: wrap(RWY_HDG - s.hdg) * 0.3, gs: 60, alt: E, vs: 600 });
  roll(10, 52, 1.5); // touchdown, roll, flaps up
  roll(8, 65, 2.5); // power up
  climbOut();
  goTo(upwind, { gs: 79, alt: E + 800 });
  goTo(xwind, { gs: 80, alt: PA });
  goTo(dwMid, { gs: 90, alt: PA });
  // Circuit 2 → bounced landing → full stop
  circuit();
  for (let i = 0; i < 3; i++) step({ turn: wrap(RWY_HDG - s.hdg) * 0.3, gs: 62, alt: E, vs: 900 });
  roll(2, 58, 2);
  // bounce: balloons ~38 ft for ~5 s, settles again
  for (const a of [24, 34, 38, 31, 23]) { step({ turn: 0, gs: 55, accel: 1 }); s.alt = E + a; pts[pts.length - 1].altFt = Math.round(s.alt); }
  roll(30, 0, 2.2); // braking to taxi speed
  roll(20, 10, 1); // vacate/taxi
  roll(5, 0, 2);

  const points = enrich(pts);
  const events = detectEvents(points, { fieldElevFt: E });
  const durSec = (pts[pts.length - 1].t - pts[0].t) / 1000;
  const d = new Date(startIso);
  const dateLabel = `${d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' })} · ${startIso.slice(11, 16)}Z`;
  return {
    id: 'sample-kapa-pattern',
    sample: true,
    label: 'SAMPLE · KAPA Steep Turns, Slow Flight & Pattern',
    airport: 'KAPA',
    fieldElevFt: E,
    origin: { lat: 39.5701, lon: -104.8484, elev: 1791 },
    startIso,
    endIso: new Date(pts[pts.length - 1].t).toISOString(),
    points,
    events,
    skills: ['Steep Turns', 'Slow Flight', 'Normal Landings', 'Traffic Pattern'],
    hours: Math.round((durSec / 3600 + 0.1) * 10) / 10, // track time + 0.1 taxi
    takeoffs: 2,
    landings: 2,
    dateLabel,
  };
}

export function sampleTrackJson() {
  return buildSampleKapaTrack();
}
